<?php
require_once __DIR__.'/../../app/layout.php';require_role('candidate');$st=db()->prepare("SELECT a.*,j.title,j.location,j.work_type,COALESCE(cp.company_name,u.name) company FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=j.company_id LEFT JOIN company_profiles cp ON cp.user_id=u.id WHERE a.candidate_id=? ORDER BY a.created_at DESC");$st->execute([current_user()['id']]);$apps=$st->fetchAll();page_header('Status lamaran');?>
<section class="page-hero"><div class="container"><span class="eyebrow">PERJALANAN KARIERMU</span><h1>Status lamaran</h1><p>Semua lamaranmu tersusun di satu tempat.</p></div></section><section class="section"><div class="container"><?php if(!$apps):?><div class="empty"><h2>Belum ada lamaran</h2><a class="btn btn-primary" href="<?=e(url('jobs.php'))?>">Cari lowongan</a></div><?php else:?><div class="panel table-wrap"><table><tr><th>Posisi</th><th>Perusahaan</th><th>Tanggal</th><th>Status</th></tr><?php foreach($apps as $a):?><tr><td><a class="link" href="<?=e(url('job.php?id='.(int)$a['job_id']))?>"><?=e($a['title'])?></a><small><?=e($a['work_type'])?> · <?=e($a['location'])?></small></td><td><?=e($a['company'])?></td><td><?=e(date('d M Y',strtotime($a['created_at'])))?></td><td><span class="badge <?=e(badge_class($a['status']))?>"><?=e($a['status'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?></div></section><?php page_footer();?>
